INSERT INTO "TaskTemplate" ("title", "description", "priority", "category", "actionType", "pulseImpact", "isActive", "triggerType", "triggerValue", "subCategory", "id", "created_date", "updated_date", "created_by_id", "created_by", "is_sample") VALUES ('Call 20 sphere contacts about referrals', 'Contact 20 people in your sphere. Ask: "Who do you know that might be thinking about buying or selling real estate in the next 6 months?"', 'medium', 'build_database', 'lead_generation', 9, TRUE, 'pulse_score_range', '41-80', NULL, '68b084e09e0eaf702538db88', '2025-08-28T16:33:36.544000', '2025-10-20T17:39:51.936000', '68a795970202102129f19984', 'officeofcjm@gmail.com', FALSE);
INSERT INTO "TaskTemplate" ("title", "description", "priority", "category", "actionType", "pulseImpact", "isActive", "triggerType", "triggerValue", "subCategory", "id", "created_date", "updated_date", "created_by_id", "created_by", "is_sample") VALUES ('Send market report to 50 contacts', 'Create a simple one-page market report with local stats and email/text it to 50 contacts with: "Thought you''d find this interesting! Let me know if you have questions."', 'medium', 'build_database', 'client_follow_up', 7, TRUE, 'pulse_score_range', '41-80', NULL, '68b084e09e0eaf702538db89', '2025-08-28T16:33:36.567000', '2025-10-20T17:39:36.958000', '68a795970202102129f19984', 'officeofcjm@gmail.com', FALSE);
INSERT INTO "TaskTemplate" ("title", "description", "priority", "category", "actionType", "pulseImpact", "isActive", "triggerType", "triggerValue", "subCategory", "id", "created_date", "updated_date", "created_by_id", "created_by", "is_sample") VALUES ('Cold call 25 homeowners in target area', 'Use skip trace to call 25 homeowners in your target neighborhood. Script: "Hi, I''m the local realtor for [Area]. I have buyers looking in your neighborhood. Any chance you''ve considered selling?"', 'medium', 'build_database', 'lead_generation', 9, TRUE, 'pulse_score_range', '41-80', NULL, '68b084e09e0eaf702538db8a', '2025-08-28T16:33:36.588000', '2025-10-20T17:39:24.099000', '68a795970202102129f19984', 'officeofcjm@gmail.com', FALSE);
INSERT INTO "TaskTemplate" ("title", "description", "priority", "category", "actionType", "pulseImpact", "isActive", "triggerType", "triggerValue", "subCategory", "id", "created_date", "updated_date", "created_by_id", "created_by", "is_sample") VALUES ('Contact 10 divorce attorneys for referrals', 'Call 10 divorce attorneys in your area. Offer to be their go-to realtor for clients who need to sell homes quickly and fairly during divorce proceedings.', 'medium', 'build_database', 'networking', 8, TRUE, 'pulse_score_range', '61-100', NULL, '68b084e19e0eaf702538db96', '2025-08-28T16:33:37.031000', '2025-10-20T17:35:46.537000', '68a795970202102129f19984', 'officeofcjm@gmail.com', FALSE);
